#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned long recyclable = 0;
unsigned long other = 0;
bool full = false;
bool previousRecyclable = false;
bool previousOther = false;
bool previousButton = false;
unsigned long lastSample = 0;
unsigned long lastReport = 0;
bool haveDistance = false;
float distanceCm = 400.0f;

float readDistance() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  if (duration == 0) return -1.0f;
  return duration * 0.0343f / 2.0f;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(7, INPUT_PULLUP);
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(8, LOW);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  display.setBrightness(7);
  display.showNumberDec(0);
  lastSample = millis() - 100UL;
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= 100UL) {
    lastSample = now;
    float measured = readDistance();
    if (measured >= 0.0f) {
      distanceCm = measured;
      haveDistance = true;
      if (distanceCm < 20.0f) full = true;
    }
  }

  bool button = digitalRead(7) == LOW;
  bool a = digitalRead(2) == LOW;
  bool b = digitalRead(3) == LOW;
  if (button && !previousButton && haveDistance && distanceCm >= 20.0f) {
    recyclable = 0;
    other = 0;
    full = false;
  }
  previousButton = button;

  if (!full) {
    if (a && !previousRecyclable) ++recyclable;
    if (b && !previousOther) ++other;
  }
  previousRecyclable = a;
  previousOther = b;

  digitalWrite(13, full ? HIGH : LOW);
  if (full) {
    tone(6, 2000);
    if (lastReport == 0 || now - lastReport >= 1000UL) {
      Serial.println("empty bin needed");
      lastReport = now;
    }
  } else {
    noTone(6);
    lastReport = 0;
  }
  display.showNumberDec((recyclable + other) % 10000UL);
  delay(5);
}
